pub fn readerPinKindName(kind: ReaderPinKind) []const u8 {
    return switch (kind) {
        .bound_read_txn => "bound_read_txn",
        .namespace_read_txn => "namespace_read_txn",
        .probe_txn => "probe_txn",
        .current_scan => "current_scan",
        .write_txn => "write_txn",
        .compaction => "compaction",
        .other => "other",
    };
}

