            try txn.commit();
        }
        for (0..64) |_| {
            _ = try backend.runMaintenanceStep();
            if (backend.pending_bulk_plan) |pending| if (pending.retry_after_ns != 0) break;
        }
        const pending = backend.pending_bulk_plan.?;
        try std.testing.expect(pending.retry_after_ns != 0);
