    var runtime = try backend.runtimeStore(std.testing.allocator, .{ .name = "docs" });
    defer runtime.deinit();
    var txn = try runtime.beginRead();
    defer txn.abort();
    try std.testing.expectEqualStrings(&([_]u8{'v'} ** 48), try txn.get("doc:000"));
